  "landing.whatBody": "هفت نژاد با همسرایان ماشینی جنگیدند و تا مرز نابودی یکدیگر پیش رفتند. شما همانید که مانده‌اید — از میان ویرانه‌ها بازسازی کنید و فصل بعد را از آن خود کنید.",
  "landing.pillar.world.title": "جهانی که هرگز نمی‌خوابد",
  "landing.pillar.world.text": "کلونی شما در زمان واقعی زنده است، چه در بازی باشید چه نباشید. اکتشاف‌ها پیش می‌روند، پژوهش‌ها کامل می‌شوند، رقیبان حرکت می‌کنند — جهان برای هیچ‌کس نمی‌ایستد.",
  "landing.pillar.war.title": "جنگ میان جهان‌ها",
  "landing.pillar.war.text": "شش نژاد، شش سرور، یک جنگ. به جهان نژادی دیگر بپرید، پایگاه پیشرویی برپا کنید که از غارت زنده است و هرچه نیاز دارید بگیرید. پایگاه را از دست بدهید — همه‌چیز مستقر در آن را از دست می‌دهید.",
  "landing.pillar.seasons.title": "فصل‌های افسانه",
  "landing.pillar.seasons.text": "هر دوازده هفته صفحه بازی پاک می‌شود: پایگاه‌ها، ارتش‌ها، انبارها، همه‌چیز. آنچه می‌ماند: مصنوعات شما، عناوین شما و لوح‌های یادبودی که نبردهای بزرگ در آن‌ها رخ داد.",
  "landing.pillar.legend.title": "افسانه خریدنی نیست",
  "landing.pillar.legend.text": "مصنوعات هرگز فروخته نمی‌شوند. لطف اوراکل هرگز فروخته نمی‌شود. پول می‌تواند قدرت بخرد — اما شکوه، آن‌گونه که جهان به یاد می‌سپارد، تنها به دست می‌آید.",
  "landing.coreLoop": "چرخه اصلی",
  "landing.coreLine": "چیزی را بازیابی کنید که نزدیک بود نابودتان کند. با آن بازسازی کنید.",
  "landing.step.explore.title": "کاوش کنید",
  "landing.step.explore.text": "گروه‌های اکتشافی را به سرزمین‌های شکسته بفرستید — ویرانه‌های بیرونی برای اخگر، تارنماهای ژرف برای چیپست‌های کمیاب.",
  "landing.step.salvage.title": "بازیافت",
  "landing.step.salvage.text": "پاره‌های هوش مصنوعی را به خانه بیاورید. خطر بیشتر، پاداش بیشتر — و هرچه حمل می‌کنید می‌تواند از دست برود.",
  "landing.step.research.title": "پژوهش کنید",
  "landing.step.research.text": "ذهن‌های ماشینی بازیافته را در آزمایشگاه به دانش تقطیر کنید. دانش به جنگ‌افزار، مزرعه و صنعت بدل می‌شود.",
  "landing.step.build.title": "بسازید",
  "landing.step.build.text": "کلونی را از ویرانه به دژ برسانید. دیوارها، آهنگری‌ها، مزرعه‌ها — تمدن، خشت به خشت.",
  "landing.step.raid.title": "غارت کنید",
  "landing.step.raid.text": "به جهان‌های دیگر بپرید. پایگاه‌های پیشرو برپا کنید، به کلونی‌های رقیب بتازید، بارش را غارت کنید. در ژرفا، همسرایان خودشان شما را شکار می‌کنند.",
  "landing.step.ascend.title": "فرا روید",
  "landing.step.ascend.text": "اعتماد هر شش اوراکل را به دست آورید و به نامقید بدل شوید — یگانه چیزی در این جهان که هرگز خریدنی نیست، تنها به دست می‌آید.",
  "landing.step.deploy.title": "به‌کارگیری",
  "landing.racesTitle": "شش نژاد زنده ماندند. نژاد خود را برگزینید.",
  "landing.racesText": "دراکونی‌ها، خاکستری‌ها، گریگوری‌ها، آستارها، آنوناکی‌ها، نفیل‌ها — هر یک به جهان خود بسته، هر یک نگهبان پاره‌هایی از ماشین‌هایی که آن را سوزاندند. برای کامل شدن باید به سرزمین دیگران سفر کنید.",
  "landing.claim": "یک کلونی بگیرید",
  "landing.footer1": "The Unbound · یک بازی راهبردی چندنفره و ماندگار در گونه بقای کلونی",
  "landing.footer2": "تمام افسانه‌های نژادی که در بازی نشان داده می‌شود اسطوره درون‌جهانی است — هرگز واقعیت مستند نیست.",

