  // ---- THE RE-TIME (owner-ratified 2026-09-26) -------------------------
  // Durations are DAY-SCALE now: the ratified ladder runs 4 h at the rim to
  // 168 h at the deepest rung, so every "returns in…" string needs units above
  // minutes. Four keys, one per scale, interpolated with nu-latn digits and
  // rendered inside `<Bdi dir="ltr">` — the number is a run of its own, or a
  // right-to-left sentence reorders it.
  "dur.day": "{d} روز {h} ساعت",
  "dur.hour": "{h} ساعت {m} دقیقه",
  "dur.minute": "{m} دقیقه {s} ثانیه",
  "dur.second": "{s} ثانیه",

  // ---- the shared primitives' own words (2026-09-28) ------------------------
  // Two strings were hard English INSIDE components the whole app draws: the
  // word `high` every MeterBar shows at >= 50%, and the accessible name of a
  // roster card's xp bar. They were the only un-keyed literals left in those two
  // primitives, so they are keys now, translated in all five files in the same
  // commit.
  "meter.high": "بالا",
  "roster.xpAria": "{name} — تجربه",


  // ---- i18n slice: tutorial (bulk keying 2026-09-30) ----
  "tutorial.cue1.line": "پیش از حرکت، نبرد را بخوان. جناح‌ها، اعداد و وضعیت خط. آن نشان حقیقت را به تو می‌گوید.",
  "tutorial.cue10.line": "مسیر برگشت در کتاب است، فرمانده. عقب‌نشینیِ استوار هزینه‌اش یک پس‌دار است اما ارتش را نجات می‌دهد؛ فرارِ وحشت‌بار هیچ‌کدام را نجات نمی‌دهد. کمک بخواه و سوار بر پیوندها می‌آید — اما رسیدنش طول می‌کشد. آن زمان را با نشکستن می‌خری.",
  "tutorial.cue11.line": "کتک خوردن را می‌شود زنده گذراند — اگر پیش از چرخش نشان انتخاب کنی. به ارتفاعات عقب بنشین و دنیا را فرا بخوان. با هم می‌بریم یا اصلاً نمی‌بریم.",
  "tutorial.cue12.line": "داشتی می‌باختی. انتخاب کردی. حالا ببین چطور برمی‌گردد.",
  "tutorial.cue13.line": "داشتی می‌باختی. انتخاب کردی. حالا ببین چطور برمی‌گردد.",
  "tutorial.cue14.line": "این شکلِ کار است، قربان. خواندی‌اش، خوراکش دادی، خمش کردی و برگرداندی، و وقتی لازم بود ما را صدا زدی. بعدی را هم همین‌طور می‌بریم — و آنِ بعدش را.",
  "tutorial.cue15.line": "شکلِ کار را می‌دانی. بخوانش، خوراکش بده، اگر شکست صدا بزن. از این به بعد کمتر حرف می‌زنم.",
  "tutorial.cue2.line": "سبز سمت توست، قرمز سمت آن‌ها. نشان می‌گوید بن‌بست — هنوز هیچ‌کس جلو نیست. وقتی به فشار متمایل شود، یعنی یکی دارد می‌برد. وقتی به خطر فرار تبدیل شود، یعنی تو داری خون می‌دهی.",
  "tutorial.cue3.line": "حالا فرمان بده. ترکیب گروه، تصمیمِ پیش از تصمیم است — انتخاب کن چه کسی می‌جنگد و کدام مهارت را زمان‌بندی کنی.",
  "tutorial.cue4.line": "نقطه‌ضعف را می‌بینم، فرمانده. مرا بگذار آنجا که خم می‌شود — نگهبان دشمن باز می‌شود مثل کتابی که فراموش کرده نوشته شده.",
  "tutorial.cue5.line": "مهارت را زمان‌بندی کن، هدرش نده. یک تصمیم در ثانیه‌ی درست از ده تصمیم در وحشت بهتر است. ما نگه می‌داریم تا تو انتخاب کنی.",
  "tutorial.cue6.line": "خط دارد خم می‌شود. تقویت کن یا نگه دار — به نبرد خوراک بده یا به موضع اعتماد کن. تصمیم بگیر.",
  "tutorial.cue7.line": "تقویت وزن بیشتری روی خط می‌گذارد؛ نگه‌داشتن هیچ هزینه‌ای ندارد و به زمین اعتماد می‌کند. وقتی در شکاف، جنگِ تن‌به‌تن است، به آن خوراک بده. وقتی زمین از بدن‌ها ارزشمندتر است، نگه دار.",
  "tutorial.cue8.line": "فشار — از آنِ ماست. خوب. حالا درسِ سخت، در حالی که هنوز داری می‌بری.",
  "tutorial.cue9.line": "و حالا — داری کتک می‌خوری. این پایان نیست. این یک تصمیم است. دو ابزار، هر دو صادقانه: دنیای خودت را به نبرد فرا بخوان، یا با نظم عقب بنشین.",

  // ---- i18n slice: tutorial-speakers (bulk keying 2026-09-30) ----
