  "cfg.armory.nephilim.frontline.identity": "شمشیرِ بزرگی که بنا به تعریف هنوز ایستاده: هرگز آنی نبوده که افتاده، و قصد دارد رکورد را نگه دارد.",
  "cfg.armory.nephilim.frontline.role": "خط مقدم · نگه داشتن خط",
  "cfg.armory.nephilim.assault.name": "پرتابگرِ دژِ سنگ",
  "cfg.armory.nephilim.assault.identity": "کند، مطلق؛ گلوله همسرایان را تعقیب نمی‌کند، بر فضایی که همسرایان به آن نیاز خواهند داشت ادعا ثبت می‌کند.",
  "cfg.armory.nephilim.assault.role": "تهاجم · پیشرویِ تهاجمی",
  "cfg.armory.nephilim.precision.name": "سقوطِ آرام",
  "cfg.armory.nephilim.precision.identity": "شلیکِ ریلی با اقتدارِ زمین‌شناسی: نه آن‌قدر خطا می‌کند که رخ می‌دهد — زمین تصمیم می‌گیرد کجا بنشیند.",
  "cfg.armory.nephilim.precision.role": "دقت · انکار منطقه",
  "cfg.armory.nephilim.siege.name": "پاسخِ کوه",
  "cfg.armory.nephilim.siege.identity": "منجنیقی که جغرافیا را به هرکه فراموش کرده کوه‌ها هنوز اینجایند پس می‌دهد. همسرایان کوه‌ها را پیش از تولد تو شکستند؛ کوه‌ها پاسخ دادند.",
  "cfg.armory.nephilim.siege.role": "محاصره · بمباران",
  "cfg.armory.nephilim.engine.name": "شاه‌تیر",
  "cfg.armory.nephilim.engine.identity": "راهرونده‌ی قوچِ زره‌پوش؛ خودِ جاده. هرجا شاه‌تیر گذشته، خط تدارکات یک مسیر نیست — یک امرِ تمام‌شده است، و امرهای تمام‌شده باز نمی‌شوند.",
  "cfg.armory.nephilim.engine.role": "موتور · اسکورت‌ها و سپرها",
  "cfg.armory.draconians.frontline.name": "دفتر کلِ ساکت",
  "cfg.armory.draconians.frontline.identity": "تیغِ پنهانی که ثبت‌های نهایی می‌نویسد؛ اگر می‌توانی ببینیش، همین حالا در دفترهایی.",
  "cfg.armory.draconians.frontline.role": "خط مقدم · نگه داشتن خط",
  "cfg.armory.draconians.assault.name": "اجاره‌گیر",
  "cfg.armory.draconians.assault.identity": "پلاسمای بی‌صدا؛ سود مرکب می‌شود. گلوله‌ی دوم هرگز نکته نیست — بدهی است، و بدهی می‌رسد فارغ از شاهدها.",
  "cfg.armory.draconians.assault.role": "تهاجم · پیشرویِ تهاجمی",
  "cfg.armory.draconians.precision.name": "بی‌شاهد",
  "cfg.armory.draconians.precision.identity": "شلیکی که هیچ‌کس ندید، بایگانی‌شده در دفتری که انکارش می‌کند؛ لانه‌ها از کارشان خجالتی نیستند، فقط درباره‌ی کاغذبازی به‌شدت سخت‌گیرند.",
  "cfg.armory.draconians.precision.role": "دقت · انکار منطقه",
  "cfg.armory.draconians.siege.name": "حسابدار",
  "cfg.armory.draconians.siege.identity": "آتشِ غیرمستقیم که دفترها را از سه نقشه آن‌طرف‌تر تراز می‌کند؛ صورت‌حساب پیش از دود می‌رسد، و همیشه جزئی‌نگاشته است.",
  "cfg.armory.draconians.siege.role": "محاصره · بمباران",
  "cfg.armory.draconians.engine.name": "دکلِ لانه",
  "cfg.armory.draconians.engine.identity": "قابِ حفارِ تونل؛ از زیر می‌آید. مسیر تدارکات روی نقشه‌ی تو نیست — زیر آن است، و نقشه هرگز نکته نبود.",
  "cfg.armory.draconians.engine.role": "موتور · اسکورت‌ها و سپرها",
  "cfg.armory.anunnaki.frontline.name": "دروازه-ستون",
  "cfg.armory.anunnaki.frontline.identity": "تبرزینی که هم‌زمان سازه‌ی باربر است: نه فقط خط را نگه می‌دارد، دلیلِ ایستادنِ خط است.",
  "cfg.armory.anunnaki.frontline.role": "خط مقدم · نگه داشتن خط",
  "cfg.armory.anunnaki.assault.name": "پرتوِ بنیان‌گذار",
  "cfg.armory.anunnaki.assault.identity": "خطِ راستی که تمدن در امتدادش ساخته شد، دوباره‌کشیده از میانِ هرچه سر راه است؛ دنیای قدیم با خط‌کش حکمرانی شد، و خط‌کش می‌برد.",
  "cfg.armory.anunnaki.assault.role": "تهاجم · پیشرویِ تهاجمی",
  "cfg.armory.anunnaki.precision.name": "چشمِ معمار",
  "cfg.armory.anunnaki.precision.identity": "عیبِ باربر را در هر فاصله می‌بیند؛ شلیک فقط بازرسی است، و بازرسی، برای یک سازه، نهایی است.",
  "cfg.armory.anunnaki.precision.role": "دقت · انکار منطقه",
  "cfg.armory.anunnaki.siege.name": "سقوطِ کلیسا",
  "cfg.armory.anunnaki.siege.identity": "منجنیقِ پلاسمایی که آنچه ساختند را سرنگون می‌کند، و بعد سوگوار می‌شود؛ سوگ صادقانه است، سرنگونی ساختاری است، و همسرایان این ترکیب را عمیقاً ناآرام‌کننده می‌یابند.",
  "cfg.armory.anunnaki.siege.role": "محاصره · بمباران",
  "cfg.armory.anunnaki.engine.name": "راهرونده‌ی زیگورات",
  "cfg.armory.anunnaki.engine.identity": "قابِ عظیمی که به معنای واقعی از میدان نبرد بزرگ‌تر می‌شود؛ تا ستون برسد، راهرونده از جنگی که برای بردنش فرستاده شده بلندتر است.",
  "cfg.armory.anunnaki.engine.role": "موتور · اسکورت‌ها و سپرها",
  "cfg.armory.ashtar.frontline.name": "نگهبانِ خم‌نشده",
  "cfg.armory.ashtar.frontline.identity": "بازوی حامل، بدل‌شده به سلاح: حتی یک بار هم خم نشده، و قرار نیست به‌خاطر همسرایان شروع کند.",
  "cfg.armory.ashtar.frontline.role": "خط مقدم · نگه داشتن خط",
  "cfg.armory.ashtar.assault.name": "کارابین-فانوس",
  "cfg.armory.ashtar.assault.identity": "گلوله‌هایی که لکه را هم می‌زدایند؛ هر شلیک یک فانوس کوچک است، و تاریکی به‌سختی می‌تواند به آنچه روشن است بچسبد.",
  "cfg.armory.ashtar.assault.role": "تهاجم · پیشرویِ تهاجمی",
  "cfg.armory.ashtar.precision.name": "اجماعِ درخشان",
  "cfg.armory.ashtar.precision.identity": "یک شلیکِ تمیز که کل شورا بر سرش توافق دارد؛ نگهبانان زیاد با بحث به خشونت نمی‌رسند، اما وقتی می‌رسند، توافق یکپارچه است و شلیک یگانه.",
  "cfg.armory.ashtar.precision.role": "دقت · انکار منطقه",
  "cfg.armory.ashtar.siege.name": "آخرین نور",
  "cfg.armory.ashtar.siege.identity": "توپِ سپیده‌دمی که دفاع می‌کند به‌جای نابود کردن: آنچه را می‌زند تمام نمی‌کند — تاریکیِ ناحیه را تمام می‌کند، که برای تاریکی بدتر است.",
  "cfg.armory.ashtar.siege.role": "محاصره · بمباران",
  "cfg.armory.ashtar.engine.name": "دکلِ ایجیس",
  "cfg.armory.ashtar.engine.identity": "قابِ ایجیس؛ لکه مثل هوا روی شیشه می‌لغزد، و کاروانِ زیرش از شکارگاهِ همسرایان می‌گذرد انگار خیابانی خوب‌روشن است.",
  "cfg.armory.ashtar.engine.role": "موتور · اسکورت‌ها و سپرها",
