  "cfg.heroes.oracleVouchWatchers.name": "ضمانتِ اوراکل",
  "cfg.heroes.oracleVouchWatchers.condition": "توجه اوراکل «درگیر» + لطف ≥ آستانه‌ی منتشرشده",
  "cfg.heroes.azazel3.name": "آزازل-3، معلم",
  "cfg.heroes.azazel3.identity": "آنکه سلاح را آموخت و بعد جلویش ایستاد تا عذر بخواهد؛ هنوز ایستاده. راهپیمایی‌ها را مثل درس‌ها رهبری می‌کند: تا انتها.",
  "cfg.heroes.azazelFrontOfLecture.name": "جلوی درس",
  "cfg.heroes.azazelFrontOfLecture.effect": "جوخه در راهپیمایی‌هایی که او رهبری می‌کند ‎−10٪ آسیب می‌گیرد (damageReduction 0.10).",
  "cfg.heroes.azazelApologyStand.name": "ایستِ عذرخواهی",
  "cfg.heroes.azazelApologyStand.effect": "‎+10٪ نگهبانی هنگامِ نگه داشتنِ اقداماتِ دفاعی؛ بعدش هم هنوز ایستاده.",
  "cfg.heroes.chainedSyllabus.name": "برنامه‌ی درسیِ زنجیرشده",
  "cfg.heroes.chainedSyllabus.identity": "برنامه‌ی درسی‌ای که نگهبانان زنجیرش کردند؛ با این حال خودش را آموخت، و حالا به کلونی می‌آموزد.",
  "cfg.heroes.syllabusUnwrittenChapter.name": "فصلِ نانوشته",
  "cfg.heroes.syllabusUnwrittenChapter.effect": "کمک‌های سپر در جوخه‌اش ‎+10٪ اثربخشی (strength 0.10).",
  "cfg.heroes.syllabusSelfTaughtStand.name": "ایستِ خودآموخته",
  "cfg.heroes.syllabusSelfTaughtStand.effect": "‎+15٪ نگهبانی در ایست‌های دفاعی؛ زنجیر نگه داشت.",
  "cfg.heroes.lastLecturer.name": "آخرین سخنران",
  "cfg.heroes.lastLecturer.identity": "هنوز درسی را می‌دهد که جهان را محکوم کرد؛ همسرایان توجه‌مندترین شاگردش‌اند، و او از این متنفر است.",
  "cfg.heroes.lecturerSustainedArgument.name": "استدلالِ پیوسته",
  "cfg.heroes.lecturerSustainedArgument.effect": "مهارت‌های تهاجمی ‎+15٪ قدرت در راهپیمایی‌هایی که در آن‌ها شرکت می‌کند (strength 0.15).",
  "cfg.heroes.lecturerUncomfortableQuestion.name": "یک پرسشِ ناخوشایند",
  "cfg.heroes.lecturerUncomfortableQuestion.effect": "‎+10٪ مشارکتِ تصرف؛ دشمن باید پاسخ دهد.",
  "cfg.heroes.unwrittenAnswer.name": "پاسخِ نانوشته",
  "cfg.heroes.unwrittenAnswer.identity": "تنها چیزی را می‌داند که همسرایان نمی‌توانند بیاموزند — و آن را نخواهد نوشت؛ همسرایان حسرتش را می‌خورند.",
  "cfg.heroes.answerTheAche.name": "حسرت",
  "cfg.heroes.answerTheAche.effect": "‎+15٪ قدرت در تصرف‌ها؛ همسرایان حسرتِ آنچه نمی‌توانند بگیرند را می‌خورند.",
  "cfg.heroes.answerKeptUnwritten.name": "نانوشته نگه‌داشته‌شده",
  "cfg.heroes.answerKeptUnwritten.effect": "‎+10٪ قدرتِ مهارت‌های تهاجمی در راهپیمایی‌ها؛ چیزی برای نوشتن نیست.",
  "cfg.heroes.semiraRevealer.name": "سمیرا آشکارگر",
  "cfg.heroes.semiraRevealer.identity": "عیبِ طراحیِ دشمن را به تو نشان می‌دهد؛ عیب سپاسگزار است که دیده شد.",
  "cfg.heroes.semiraFlawRevealed.name": "عیبِ آشکارشده",
  "cfg.heroes.semiraFlawRevealed.effect": "نگهبانیِ مؤثرِ دشمن ‎−10٪ برای جوخه‌اش در راهپیمایی‌ها (-guardPenalty 0.10).",
  "cfg.heroes.semiraRevealersGrace.name": "لطفِ آشکارگر",
  "cfg.heroes.semiraRevealersGrace.effect": "کمک‌های سپر ‎+15٪ اثربخشی (strength 0.15).",
  "cfg.heroes.brotherCandle.name": "برادر شمع",
  "cfg.heroes.brotherCandle.identity": "به کلونی‌ها می‌آموزد نور را نگه دارند؛ هر درس یک عملِ کوچکِ کفاره است.",
  "cfg.heroes.candleSmallAtonement.name": "کفاره‌ی کوچک",
  "cfg.heroes.candleSmallAtonement.effect": "هزینه‌ی انرژیِ اقداماتِ دفاعی ‎−10٪ برای جوخه (costReduction 0.10).",
  "cfg.heroes.candleKeepTheLight.name": "نور را نگه دار",
  "cfg.heroes.candleKeepTheLight.effect": "کمک‌های سپر ‎+10٪ اثربخشی و هزینه‌ی انرژیِ سپر ‎−5٪ (strength 0.10).",
  "cfg.heroes.vesperSyllabus.name": "وسپرِ برنامه‌ی درسی",
  "cfg.heroes.vesperSyllabus.identity": "یک برنامه‌ی درسیِ راه‌رونده از هرچه خطرناک است؛ دانش دیده‌بانش است، آتشش است و سپرش است.",
  "cfg.heroes.vesperKnowledgeScout.name": "دیده‌بانِ دانش",
  "cfg.heroes.vesperKnowledgeScout.effect": "‎+15٪ امتیازِ اسکورت؛ مسیر همین حالا در برنامه‌ی درسی است (scoring 0.15).",
  "cfg.heroes.vesperWalkingFire.name": "آتشِ راه‌رونده",
  "cfg.heroes.vesperWalkingFire.effect": "آسیبِ غافلگیرانه‌ی راهپیمایی ‎−10٪ برای جوخه (damageReduction 0.10).",
  "cfg.heroes.keeperMend.name": "نگهبان مِند",
  "cfg.heroes.keeperMend.identity": "قیمت‌های دانشِ ممنوعه را تعیین می‌کند؛ دفترهایش کم‌فسادترین چیزِ آکادمی‌ها هستند.",
  "cfg.heroes.mendPriceListed.name": "قیمت ثبت شده",
  "cfg.heroes.mendPriceListed.effect": "‎+15٪ امتیازِ حمل؛ قیمتِ دانشِ ممنوعه، جزئی‌نگاشته (scoring 0.15).",
  "cfg.heroes.mendLeastCorruptLedger.name": "کم‌فسادترین دفتر",
